// Lecture 1 game "You or the network?": the student decides on real HMEQ loans, then sees the network's decision and the outcome.
// Data: L1_game_data.js (generated by lectures/L1/make_game_L1.py). Page language: window.NN_LANG ('en' or 'ro').
(function () {
  'use strict';
  const G = window.NN_GAME_L1, RO = window.NN_LANG === 'ro', I = G.info;
  const nf = (x, d) => x.toLocaleString(RO ? 'ro-RO' : 'en-US', { minimumFractionDigits: d || 0, maximumFractionDigits: d || 0 });
  const pct = (x, d) => nf(100 * x, d === undefined ? 1 : d) + (RO ? ' %' : '%');
  const TX = RO ? {
    start: 'Începe jocul', next: 'Următorul dosar', again: 'Joacă din nou', approve: 'Aprob creditul', refuse: 'Resping creditul',
    card: (k, n) => `Dosarul ${k} din ${n}`, missing: 'necunoscut',
    you: 'Decizia dumneavoastră', net: 'Rețeaua din curs', out: 'Ce s-a întîmplat',
    approved: 'aprobat', refused: 'respins', repaid: 'a rambursat creditul', defaulted: 'nu a plătit (neplată)',
    pd: p => `probabilitatea de neplată ${pct(p)}`, right: 'corect', wrong: 'greșit',
    score: 'Scor', you2: 'Dumneavoastră', net2: 'Rețeaua',
    reason: { DebtCon: 'consolidarea datoriilor', HomeImp: 'renovarea locuinței' },
    job: { Mgr: 'manager', Office: 'funcționar', Other: 'altă ocupație', ProfExe: 'profesie liberală sau director', Sales: 'vînzări', Self: 'pe cont propriu' },
    rows: [['loan', 'Suma cerută', 'USD'], ['mortdue', 'Datoria rămasă pe ipoteca existentă', 'USD'], ['value', 'Valoarea locuinței', 'USD'],
      ['reason', 'Scopul creditului'], ['job', 'Ocupația'], ['yoj', 'Ani la locul de muncă actual'], ['derog', 'Rapoarte negative majore în istoricul de credit'],
      ['delinq', 'Linii de credit cu restanțe'], ['clage', 'Vechimea celei mai vechi linii de credit', 'ani'], ['ninq', 'Cereri recente de credit'],
      ['clno', 'Număr de linii de credit'], ['debtinc', 'Datorii / venit', '%']],
    end: (y, m, n) => `Ați decis corect în ${y} din ${n} cazuri; rețeaua, în ${m} din ${n}.`,
    caught: (a, b) => `Neplăți oprite: dumneavoastră ${a}, rețeaua ${b}.`,
    lost: (a, b) => `Clienți buni respinși: dumneavoastră ${a}, rețeaua ${b}.`
  } : {
    start: 'Start the game', next: 'Next application', again: 'Play again', approve: 'Approve the loan', refuse: 'Refuse the loan',
    card: (k, n) => `Application ${k} of ${n}`, missing: 'not reported',
    you: 'Your decision', net: 'The network of the lecture', out: 'What happened',
    approved: 'approved', refused: 'refused', repaid: 'repaid the loan', defaulted: 'defaulted',
    pd: p => `probability of default ${pct(p)}`, right: 'right', wrong: 'wrong',
    score: 'Score', you2: 'You', net2: 'Network',
    reason: { DebtCon: 'debt consolidation', HomeImp: 'home improvement' },
    job: { Mgr: 'manager', Office: 'office worker', Other: 'other', ProfExe: 'professional or executive', Sales: 'sales', Self: 'self-employed' },
    rows: [['loan', 'Amount requested', 'USD'], ['mortdue', 'Amount still due on the existing mortgage', 'USD'], ['value', 'Value of the home', 'USD'],
      ['reason', 'Purpose of the loan'], ['job', 'Occupation'], ['yoj', 'Years at the present job'], ['derog', 'Major derogatory reports in the credit history'],
      ['delinq', 'Delinquent credit lines'], ['clage', 'Age of the oldest credit line', 'years'], ['ninq', 'Recent credit inquiries'],
      ['clno', 'Number of credit lines'], ['debtinc', 'Debt-to-income ratio', '%']],
    end: (y, m, n) => `You decided correctly in ${y} of ${n} cases; the network in ${m} of ${n}.`,
    caught: (a, b) => `Defaults stopped: you ${a}, the network ${b}.`,
    lost: (a, b) => `Good clients refused: you ${a}, the network ${b}.`
  };
  const $ = id => document.getElementById(id);
  let deck = [], k = 0, res = [];

  function shuffle(a) {
    for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
    return a;
  }
  function draw() {   // a third of the cards are defaults, as in the pool (12 of 36)
    const bad = shuffle(G.pool.filter(c => c.bad)), good = shuffle(G.pool.filter(c => !c.bad));
    const nb = Math.round(I.per_game * I.pool_bad / (I.pool_bad + I.pool_good));
    return shuffle(bad.slice(0, nb).concat(good.slice(0, I.per_game - nb)));
  }
  function val(c, key, unit) {
    const v = c[key];
    if (v === null || v === undefined) return `<span class="g-miss">${TX.missing}</span>`;
    if (key === 'reason') return TX.reason[v] || v;
    if (key === 'job') return TX.job[v] || v;
    if (key === 'clage') return nf(v / 12, 1) + ' ' + unit;
    if (key === 'yoj') return nf(v, 1);
    if (key === 'debtinc') return nf(v, 1) + (RO ? ' %' : '%');
    return nf(v) + (unit ? ' ' + unit : '');
  }
  function score() {
    const y = res.filter(r => r.you === r.bad).length, m = res.filter(r => r.net === r.bad).length;
    $('g-score').innerHTML = `${TX.score}: <b>${TX.you2} ${y}</b> · <b>${TX.net2} ${m}</b> <span class="g-of">/ ${res.length}</span>`;
  }
  function show() {
    const c = deck[k];
    $('g-card').innerHTML = `<h3>${TX.card(k + 1, deck.length)}</h3><table class="g-tab"><tbody>` +
      TX.rows.map(([key, lab, unit]) => `<tr><th scope="row">${lab}</th><td>${val(c, key, unit)}</td></tr>`).join('') + '</tbody></table>' +
      `<div class="g-act"><button type="button" class="btn g-ok" id="g-a">${TX.approve}</button><button type="button" class="btn g-no" id="g-r">${TX.refuse}</button></div><div id="g-rev" aria-live="polite"></div>`;
    $('g-a').onclick = () => decide(0);
    $('g-r').onclick = () => decide(1);
    $('g-a').focus();
  }
  function decide(you) {
    const c = deck[k], net = c.p >= 0.5 ? 1 : 0;
    res.push({ you, net, bad: c.bad });
    $('g-a').disabled = $('g-r').disabled = true;
    const mark = ok => `<span class="${ok ? 'g-right' : 'g-wrong'}">${ok ? '✓ ' + TX.right : '✗ ' + TX.wrong}</span>`;
    $('g-rev').innerHTML = '<ul class="g-res">' +
      `<li>${TX.you}: <b>${you ? TX.refused : TX.approved}</b> ${mark(you === c.bad)}</li>` +
      `<li>${TX.net}: <b>${net ? TX.refused : TX.approved}</b> (${TX.pd(c.p)}) ${mark(net === c.bad)}</li>` +
      `<li>${TX.out}: <b>${c.bad ? TX.defaulted : TX.repaid}</b></li></ul>` +
      `<button type="button" class="btn play" id="g-n">${k + 1 < deck.length ? TX.next : (RO ? 'Vezi rezultatul' : 'See the result')}</button>`;
    score();
    $('g-n').onclick = () => { k++; k < deck.length ? show() : finish(); };
    $('g-n').focus();
  }
  function finish() {
    const n = res.length, y = res.filter(r => r.you === r.bad).length, m = res.filter(r => r.net === r.bad).length;
    const cy = res.filter(r => r.bad && r.you).length, cm = res.filter(r => r.bad && r.net).length;
    const ly = res.filter(r => !r.bad && r.you).length, lm = res.filter(r => !r.bad && r.net).length;
    $('g-card').innerHTML = `<h3>${RO ? 'Rezultatul' : 'The result'}</h3><p class="g-big">${TX.end(y, m, n)}</p><ul class="g-res"><li>${TX.caught(cy, cm)}</li><li>${TX.lost(ly, lm)}</li></ul>` +
      sendForm() + $('g-lesson').innerHTML + `<button type="button" class="btn play" id="g-s2">${TX.again}</button>`;
    $('g-s2').onclick = start;
    const f = $('g-send');
    if (f) f.onsubmit = ev => { ev.preventDefault(); send({ you: y, net: m, total: n, caught: cy, lost: ly }); };
  }

  // ---- class board: the first finished game of the day on this device goes to the instructor's sheet (anonymous, nickname)
  const URL_ = (window.NN_CONFIG || {}).QUIZ_SCORES_URL || '';
  const SESSION = (() => { const d = new Date(); return '' + d.getFullYear() + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0'); })();
  const KEY = 'nn_game_l1_' + SESSION;
  const store = { get: () => { try { return localStorage.getItem(KEY); } catch (e) { return null; } },
                  set: v => { try { localStorage.setItem(KEY, v); } catch (e) { /* private mode: nothing kept */ } } };
  const S = RO ? { h: 'Clasamentul sălii', nick: 'Pseudonim (apare pe ecranul din sală, nu folosiți numele real)', send: 'Trimite rezultatul',
      sent: 'Rezultatul a fost trimis. Doar primul joc al zilei intră în clasament.', done: 'Ați trimis deja rezultatul de azi; jocurile următoare nu mai intră în clasament.',
      fail: 'Rezultatul nu a putut fi trimis.', sending: 'Se trimite…' }
    : { h: 'Class board', nick: 'Nickname (shown on the screen in the room; do not use your real name)', send: 'Send my result',
      sent: 'Your result was sent. Only the first game of the day counts on the board.', done: 'You already sent today\'s result; later games do not count on the board.',
      fail: 'The result could not be sent.', sending: 'Sending…' };
  function sendForm() {
    if (!/^https:\/\/script\.google\.com\//.test(URL_)) return '';
    if (store.get()) return `<p class="g-note">${S.done}</p>`;
    return `<form id="g-send" class="g-send"><h4>${S.h}</h4><label for="g-nick">${S.nick}</label>` +
      `<div class="g-row"><input id="g-nick" maxlength="20" autocomplete="off" required><button type="submit" class="btn">${S.send}</button></div><p id="g-st" class="g-note" aria-live="polite"></p></form>`;
  }
  function send(r) {
    const st = $('g-st'), b = $('g-send').querySelector('button');
    b.disabled = true; st.textContent = S.sending;
    fetch(URL_, { method: 'POST', headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify(Object.assign({ type: 'game', game: 'l1', session: SESSION, nick: $('g-nick').value, lang: RO ? 'ro' : 'en' }, r)) })
      .then(x => x.json()).then(j => {
        if (j.ok) { store.set('1'); st.textContent = S.sent; $('g-nick').disabled = true; } else { st.textContent = S.fail; b.disabled = false; }
      }).catch(() => { st.textContent = S.fail; b.disabled = false; });
  }
  function start() {
    deck = draw(); k = 0; res = [];
    $('g-score').innerHTML = '';
    show();
  }
  $('g-s').textContent = TX.start;
  $('g-s').onclick = () => { $('g-intro').hidden = true; $('g-play').hidden = false; start(); };
})();
